package hvac_energy_interface_supervisor.HVAC_Energy_Interface_Supervisor

import org.sireum._
import art._
import hvac_energy_interface_supervisor._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait EnergyCapabilityQualifier_Api {
  def id: Art.BridgeId
  def energyContext_Id : Art.PortId
  def energyCapability_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var energyCapability: HVAC_Energy_Interface_Supervisor.EnergyCapability.Type = $

  def put_energyCapability(value : HVAC_Energy_Interface_Supervisor.EnergyCapability.Type) : Unit = {
    Contract(
      Modifies(energyCapability),
      Ensures(
        energyCapability == value
      )
    )
    Spec {
      energyCapability = value
    }

    Art.putValue(energyCapability_Id, HVAC_Energy_Interface_Supervisor.EnergyCapability_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class EnergyCapabilityQualifier_Initialization_Api (
  val id: Art.BridgeId,
  val energyContext_Id : Art.PortId,
  val energyCapability_Id : Art.PortId) extends EnergyCapabilityQualifier_Api

@datatype class EnergyCapabilityQualifier_Operational_Api (
  val id: Art.BridgeId,
  val energyContext_Id : Art.PortId,
  val energyCapability_Id : Art.PortId) extends EnergyCapabilityQualifier_Api {

  // Logika spec var representing port state for incoming data port
  @spec var energyContext: HVAC_Energy_Interface_Supervisor.EnergyContext = $

  def get_energyContext() : Option[HVAC_Energy_Interface_Supervisor.EnergyContext] = {
    Contract(
      Ensures(
        Res == Some(energyContext)
      )
    )
    val value : Option[HVAC_Energy_Interface_Supervisor.EnergyContext] = Art.getValue(energyContext_Id) match {
      case Some(HVAC_Energy_Interface_Supervisor.EnergyContext_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port energyContext.  Expecting 'HVAC_Energy_Interface_Supervisor.EnergyContext_Payload' but received ${v}")
        None[HVAC_Energy_Interface_Supervisor.EnergyContext]()
      case _ => None[HVAC_Energy_Interface_Supervisor.EnergyContext]()
    }
    return value
  }
}
